// Source-independent video timing. A paused scrub seeks; playback is drift-corrected.
export const mediaClipDefaults={gestureVideoEnabled:true,gestureVideoIn:0,gestureVideoOut:3,gestureVideoRate:1,gestureVideoLoop:false,gestureVideoScale:1,gestureVideoX:0,gestureVideoY:0};
export function mediaClipTime(elapsed,{start=0,end=Infinity,rate=1,loop=false,duration=Infinity}={}){const a=Math.max(0,Math.min(start,duration)),b=Math.max(a,Math.min(end,duration)),span=b-a,age=Math.max(0,elapsed)*Math.max(.05,rate);return a+(loop&&span>0?age%span:Math.min(age,Math.max(0,span-1/240)))}
export function syncMediaClip(media,elapsed,options={}){const desired=mediaClipTime(elapsed,{...options,duration:media.duration||options.duration||10});if(media._offlineFrame)return media._offlineFrame(desired);if(!('currentTime'in media))return media;const hold=elapsed<0||desired>=Math.min(options.end??Infinity,media.duration||Infinity)-1/120,play=options.playing&&!hold;media.playbackRate=Math.max(.05,options.rate||1);if(!media.seeking&&Math.abs(media.currentTime-desired)>(play?.14:1/48))media.currentTime=desired;if(play){if(media.paused)media.play().catch(()=>{})}else media.pause();return media}
export function mediaReady(media){return !!media&&(media.videoWidth>0&&media.readyState>=2||media.naturalWidth>0||media.width>0)}
